import type { BankQuestion } from "@/lib/bank";

/** MS Office, Internet and Cyber Security (Computer Awareness): 149 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id": "comp-ms-office-internet-1", "question": "Which keyboard shortcut selects all the content of a document in MS Word?", "options": ["Ctrl + L", "Ctrl + E", "Ctrl + A", "Ctrl + S"], "answer": 2, "explanation": "Ctrl + A selects all. Ctrl + S saves, Ctrl + L left-aligns and Ctrl + E centres the text.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "comp-ms-office-internet-2", "question": "What is the default file extension of an MS Excel workbook saved in Excel 2007 or later?", "options": [".docx", ".accdb", ".pptx", ".xlsx"], "answer": 3, "explanation": ".xlsx is the Excel workbook format (Office Open XML). .docx is Word, .pptx is PowerPoint and .accdb is an Access database.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "comp-ms-office-internet-3", "question": "A malicious program that looks like useful software but secretly harms the system once installed is called a:", "options": ["Firewall", "Trojan horse", "Worm", "Cookie"], "answer": 1, "explanation": "A Trojan horse disguises itself as legitimate software. A worm spreads by itself across networks; a firewall is a defence and a cookie is a small browser file.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "comp-ms-office-internet-4", "question": "Which key starts a PowerPoint slide show from the first slide?", "options": ["F5", "F12", "F1", "F7"], "answer": 0, "explanation": "F5 runs the slide show from the beginning (Shift + F5 starts from the current slide). F7 is spell check, F12 is Save As and F1 is Help.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "comp-ms-office-internet-5", "question": "Which MS Excel function counts only the cells in a range that contain numbers?", "options": ["COUNT", "COUNTA", "COUNTBLANK", "SUM"], "answer": 0, "explanation": "COUNT counts numeric cells only. COUNTA counts every non-empty cell (text included), COUNTBLANK counts empty cells and SUM adds values.", "difficulty": "moderate", "source": "IBPS PO · SBI Clerk · SSC CGL"},
  {"id": "comp-ms-office-internet-6", "question": "An e-mail pretending to be from your bank that asks you to click a link and enter your login details is an example of:", "options": ["Spamdexing", "Cracking", "Phishing", "Vishing"], "answer": 2, "explanation": "Phishing uses fake e-mails or websites to steal credentials. Vishing is the same trick over voice calls.", "difficulty": "moderate", "source": "IBPS PO · SBI Clerk · SSC CGL"},
  {"id": "comp-ms-office-internet-7", "question": "In MS Word, the shortcut Ctrl + E is used to:", "options": ["Right-align the text", "Justify the text", "Open the Find dialog", "Centre-align the text"], "answer": 3, "explanation": "Ctrl + E centres, Ctrl + J justifies, Ctrl + R right-aligns, Ctrl + L left-aligns and Ctrl + F opens Find.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "comp-ms-office-internet-8", "question": "Which protocol lets you read e-mail while keeping the messages on the server, so the mailbox stays in sync on your phone and laptop?", "options": ["POP3", "IMAP", "SMTP", "FTP"], "answer": 1, "explanation": "IMAP keeps mail on the server and syncs folders across devices. POP3 typically downloads mail to one device and removes it from the server; SMTP only sends mail.", "difficulty": "moderate", "source": "IBPS PO · SBI Clerk · SSC CGL"},
  {"id": "comp-ms-office-internet-9", "question": "PDF, the common document format developed by Adobe, stands for:", "options": ["Printable Document File", "Portable Document Format", "Portable Data File", "Public Data Format"], "answer": 1, "explanation": "PDF = Portable Document Format, introduced by Adobe in 1993 so a document looks the same on every device.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "comp-ms-office-internet-10", "question": "Which device forwards data packets between different networks using IP addresses?", "options": ["Hub", "Repeater", "Switch", "Router"], "answer": 3, "explanation": "A router works at the network layer and routes packets between networks by IP address. A switch forwards frames within a LAN using MAC addresses; a hub and repeater only regenerate signals.", "difficulty": "moderate", "source": "IBPS PO · SBI Clerk · SSC CGL"},
  {"id": "comp-ms-office-internet-11", "question": "A system that monitors incoming and outgoing network traffic and blocks it according to set security rules is a:", "options": ["Firewall", "Compiler", "Modem", "Proxy server"], "answer": 0, "explanation": "A firewall (hardware or software) filters traffic by rules. A proxy forwards requests on a client's behalf; it is not primarily a rule-based filter.", "difficulty": "moderate", "source": "IBPS PO · SBI Clerk · SSC CGL"},
  {"id": "comp-ms-office-internet-12", "question": "In MS Excel, which cell reference remains unchanged when a formula is copied to another cell?", "options": ["A$1", "$A1", "$A$1", "A1"], "answer": 2, "explanation": "$A$1 is an absolute reference: both column and row are locked. A1 is relative, while A$1 and $A1 are mixed references that lock only the row or only the column.", "difficulty": "moderate", "source": "IBPS PO · SBI Clerk · SSC CGL"},
  {"id": "comp-ms-office-internet-13", "question": "What value does the Excel formula =INT(-4.3) return?", "options": ["-5", "-4", "-4.3", "4"], "answer": 0, "explanation": "INT rounds a number down to the nearest integer, so -4.3 becomes -5 (not -4). TRUNC(-4.3) would give -4.", "difficulty": "hard", "source": "IBPS PO · SBI PO · RRB NTPC"},
  {"id": "comp-ms-office-internet-14", "question": "The WannaCry attack of May 2017, which locked files on computers worldwide and demanded payment in Bitcoin, was an example of:", "options": ["Keylogger", "Ransomware", "Adware", "Spyware"], "answer": 1, "explanation": "Ransomware encrypts the victim's files and demands a ransom for the key. WannaCry spread through a Windows SMB vulnerability.", "difficulty": "hard", "source": "IBPS PO · SBI PO · RRB NTPC"},
  {"id": "comp-ms-office-internet-16", "question": "Which Excel function searches for a value in the top row of a table and returns a value from a specified row below it?", "options": ["MATCH", "VLOOKUP", "HLOOKUP", "CONCAT"], "answer": 2, "explanation": "HLOOKUP looks across the first row (horizontal). VLOOKUP looks down the first column; MATCH returns only a position.", "difficulty": "hard", "source": "IBPS PO · SBI PO · RRB NTPC"},
  {"id": "comp-ms-office-internet-17", "question": "An IPv6 address is how many bits long?", "options": ["256", "64", "128", "32"], "answer": 2, "explanation": "IPv6 addresses are 128 bits, written as eight groups of four hexadecimal digits. IPv4 addresses are 32 bits.", "difficulty": "hard", "source": "IBPS PO · SBI Clerk · SSC CGL"},
  {"id": "comp-ms-office-internet-18", "question": "Which type of malware copies itself from computer to computer over a network without attaching to a host file and without user action?", "options": ["Adware", "Worm", "Trojan horse", "Virus"], "answer": 1, "explanation": "A worm is self-replicating and standalone. A virus needs a host file and usually needs that file to be run; a Trojan does not replicate.", "difficulty": "hard", "source": "IBPS PO · SBI Clerk · SSC CGL"},
  {"id": "comp-ms-office-internet-19", "question": "Logging in with a password followed by an OTP sent to your registered mobile number is an example of:", "options": ["Two-factor authentication", "Single sign-on", "Biometric authentication", "CAPTCHA verification"], "answer": 0, "explanation": "It combines something you know (password) with something you have (the phone receiving the OTP), which is two-factor authentication.", "difficulty": "hard", "source": "IBPS PO · SBI PO · RRB NTPC"},
  {"id": "comp-ms-office-internet-20", "question": "In MS Word, pressing F7 opens:", "options": ["Help", "Save As dialog", "Thesaurus", "Spelling and Grammar check"], "answer": 3, "explanation": "F7 runs Spelling and Grammar. Shift + F7 opens the Thesaurus, F12 is Save As and F1 is Help.", "difficulty": "hard", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "comp-ms-office-internet-21", "question": "In Excel, A1 = 10, A2 is blank, A3 = “Yes”, A4 = 0 and A5 is blank. What does =COUNTA(A1:A5) return?", "options": ["2", "3", "5", "1"], "answer": 1, "explanation": "COUNTA counts non-empty cells: A1, A3 and A4 → 3. COUNT would return 2 because it ignores the text in A3; a zero is still a value.", "difficulty": "hard", "source": "IBPS PO · SBI PO · RRB NTPC"},
  {"id": "comp-ms-office-internet-22", "question": "A small text file that a website stores in your browser to remember your login or preferences is called a:", "options": ["Cache", "Plug-in", "Applet", "Cookie"], "answer": 3, "explanation": "Cookies are small text files stored by websites. The cache stores copies of web pages and images to load them faster.", "difficulty": "hard", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "comp-ms-office-internet-23", "question": "Which image format uses lossy compression and is the most common choice for photographs?", "options": ["JPEG", "BMP", "GIF", "PNG"], "answer": 0, "explanation": "JPEG discards some detail to shrink file size (lossy). PNG and GIF are lossless (GIF is limited to 256 colours) and BMP is usually uncompressed.", "difficulty": "hard", "source": "IBPS PO · SBI Clerk · SSC CGL"},
  {"id": "comp-ms-office-internet-24", "question": "A network that covers a city, such as a cable TV network or a city-wide network linking a bank's branches, is a:", "options": ["PAN", "LAN", "MAN", "WAN"], "answer": 2, "explanation": "MAN (Metropolitan Area Network) spans a city. LAN covers a building or campus, PAN a person's devices and WAN countries or continents.", "difficulty": "hard", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "comp-ms-office-internet-25", "question": "How many of these MS Word shortcuts are correctly described? I. Ctrl + Home moves the cursor to the beginning of the document. II. Ctrl + Enter inserts a page break. III. Ctrl + K inserts a hyperlink. IV. Ctrl + D duplicates the selected line.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and III are correct. IV is wrong: Ctrl + D in Word opens the Font dialog box.", "difficulty": "very-hard", "source": "IBPS PO · SBI Clerk · SSC CGL"},
  {"id": "comp-ms-office-internet-26", "question": "Match the malware with its description: 1. Keylogger 2. Rootkit 3. Adware 4. Spyware; a. Hides deep in the operating system to keep privileged access b. Shows unwanted advertisements c. Records every keystroke d. Secretly collects user information and sends it to a third party", "options": ["1-a, 2-c, 3-b, 4-d", "1-c, 2-a, 3-d, 4-b", "1-c, 2-a, 3-b, 4-d", "1-d, 2-a, 3-b, 4-c"], "answer": 2, "explanation": "Keylogger records keystrokes (c), rootkit hides in the OS with admin-level access (a), adware shows ads (b), spyware gathers information and sends it out (d).", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · RRB NTPC"},
  {"id": "comp-ms-office-internet-27", "question": "In Excel, A1 = 5, A2 = 10, A3 = 15, A4 contains the text “abc” and A5 is blank. What does =AVERAGE(A1:A5) return?", "options": ["7.5", "6", "#VALUE!", "10"], "answer": 3, "explanation": "AVERAGE ignores text and empty cells in a range: (5 + 10 + 15)/3 = 10. Dividing by 5 cells (6) or 4 cells (7.5) is the trap.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · RRB NTPC"},
  {"id": "comp-ms-office-internet-28", "question": "Every cell from A1 to C4 contains the number 2. What does the formula =SUM(A1:C4)/COUNT(B1:B4) return?", "options": ["12", "6", "8", "3"], "answer": 1, "explanation": "A1:C4 has 3 columns × 4 rows = 12 cells, so SUM = 24. COUNT(B1:B4) = 4. 24 ÷ 4 = 6.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · RRB NTPC"},
  {"id": "comp-ms-office-internet-29", "question": "In Excel, A1 = 60 and B1 = 45. What does =IF(AND(A1>50,B1>50),\"Pass\",\"Fail\") return?", "options": ["Fail", "FALSE", "Pass", "#VALUE!"], "answer": 0, "explanation": "AND needs both conditions true; B1 > 50 is false, so AND returns FALSE and IF gives “Fail”. With OR instead of AND, the result would be “Pass”.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · RRB NTPC"},
  {"id": "comp-ms-office-internet-30", "question": "Arrange in chronological order: 1. First message sent over ARPANET 2. Tim Berners-Lee proposes the World Wide Web at CERN 3. ARPANET switches to TCP/IP 4. VSNL launches public internet service in India", "options": ["1, 2, 3, 4", "1, 3, 4, 2", "3, 1, 2, 4", "1, 3, 2, 4"], "answer": 3, "explanation": "ARPANET's first message (1969), ARPANET adopts TCP/IP (1 January 1983), WWW proposal (1989), VSNL public internet in India (15 August 1995). Order: 1, 3, 2, 4.", "difficulty": "very-hard", "source": "IBPS PO · SBI Clerk · SSC CGL"},
  {"id": "comp-ms-office-internet-31", "question": "How many of these statements are correct? I. Phishing through SMS messages is called smishing. II. Vishing uses voice calls to trick victims. III. A DDoS attack floods a server with traffic from many compromised machines. IV. Pharming means tricking a person into revealing an OTP over a phone call.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and III are correct. IV is wrong: pharming redirects users to a fake website even when they type the correct address, often through DNS poisoning; the phone-call trick is vishing.", "difficulty": "very-hard", "source": "IBPS PO · SBI Clerk · SSC CGL"},
  {"id": "comp-ms-office-internet-32", "question": "Assertion (A): HTTPS is safer than HTTP for internet banking. Reason (R): HTTPS uses port 80 by default.", "options": ["Both A and R are true, and R is the correct explanation of A", "Both A and R are true, but R is not the correct explanation of A", "A is true, but R is false", "A is false, but R is true"], "answer": 2, "explanation": "A is true because HTTPS encrypts traffic with TLS. R is false: HTTPS uses port 443; port 80 is plain HTTP.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · RRB NTPC"},
  {"id": "comp-ms-office-internet-33", "question": "How many of these are valid IPv4 addresses? 192.168.0.255, 256.10.1.1, 10.10.10, 172.31.0.1", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 1, "explanation": "An IPv4 address has four octets, each from 0 to 255. 192.168.0.255 and 172.31.0.1 are valid; 256.10.1.1 has an octet above 255 and 10.10.10 has only three octets. So only two.", "difficulty": "very-hard", "source": "IBPS PO · SBI Clerk · SSC CGL"},
  {"id": "comp-ms-office-internet-34", "question": "Match the file extension with what it stores: 1. .pptx 2. .accdb 3. .xlsm 4. .dotx; a. Access database b. Macro-enabled Excel workbook c. Word template d. PowerPoint presentation", "options": ["1-d, 2-a, 3-c, 4-b", "1-d, 2-b, 3-a, 4-c", "1-d, 2-a, 3-b, 4-c", "1-a, 2-d, 3-b, 4-c"], "answer": 2, "explanation": ".pptx is a PowerPoint presentation, .accdb an Access database, .xlsm an Excel workbook with macros enabled and .dotx a Word template.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · RRB NTPC"},
  {"id": "comp-ms-office-internet-35", "question": "In Excel, A1 = 25 and B1 is empty. What does =A1/B1 return?", "options": ["#DIV/0!", "25", "0", "#VALUE!"], "answer": 0, "explanation": "An empty cell is treated as 0 in arithmetic, so the formula divides by zero and returns #DIV/0!. #VALUE! appears when a wrong data type, such as text, is used.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · RRB NTPC"},
  {"id": "comp-ms-office-internet-36", "question": "A broadband connection has a speed of 100 Mbps. What is the maximum amount of data it can transfer per second, in megabytes?", "options": ["800 MB", "12.5 MB", "10 MB", "100 MB"], "answer": 1, "explanation": "Mbps is megabits per second and 1 byte = 8 bits, so 100 ÷ 8 = 12.5 megabytes per second.", "difficulty": "very-hard", "source": "IBPS PO · SBI Clerk · SSC CGL"},
  {"id": "comp-ms-office-internet-37", "question": "How many of these statements about e-mail are correct? I. Recipients in the CC field are visible to all recipients. II. Recipients in the BCC field are hidden from the other recipients. III. SMTP is the protocol a mail client uses to download messages from the server. IV. POP3 uses port 110 by default.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and IV are correct. III is wrong: SMTP sends mail; POP3 or IMAP is used to retrieve it.", "difficulty": "very-hard", "source": "IBPS PO · SBI Clerk · SSC CGL"},
  {"id": "comp-ms-office-internet-38", "question": "In which case did the Supreme Court strike down Section 66A of the Information Technology Act, 2000 in 2015?", "options": ["Shreya Singhal v. Union of India", "Anuradha Bhasin v. Union of India", "Justice K.S. Puttaswamy v. Union of India", "Vishaka v. State of Rajasthan"], "answer": 0, "explanation": "Shreya Singhal (2015) struck down Section 66A, which punished “offensive” online messages, as violating free speech. Puttaswamy (2017) declared privacy a fundamental right; Anuradha Bhasin (2020) dealt with internet shutdowns.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · RRB NTPC"},
  {"id": "comp-ms-office-internet-39", "question": "Assertion (A): A computer virus usually cannot spread until an infected file or program is executed. Reason (R): A virus attaches its code to a host program or file.", "options": ["Both A and R are true, and R is the correct explanation of A", "Both A and R are true, but R is not the correct explanation of A", "A is true, but R is false", "A is false, but R is true"], "answer": 0, "explanation": "Both are true. Because a virus lives inside a host program, its code runs, and copies itself, only when that host is run, so R explains A. This is what separates it from a worm.", "difficulty": "very-hard", "source": "IBPS PO · SBI Clerk · SSC CGL"},
  {"id": "comp-ms-office-internet-40", "question": "How many of these statements are correct? I. CERT-In works under the Ministry of Electronics and Information Technology. II. The IT Act, 2000 gave legal recognition to electronic records and digital signatures. III. 1930 is the national cyber-crime helpline number. IV. The Digital Personal Data Protection Act was passed in 2023.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 3, "explanation": "All four are correct: CERT-In is under MeitY, the IT Act 2000 recognises e-records and digital signatures, 1930 is the cyber-fraud helpline and the DPDP Act was enacted in August 2023.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · RRB NTPC"},
  {"id":"comp-ms-office-internet-41","question":"In MS Word, which shortcut inserts a manual page break at the cursor position?","options":["Ctrl + Enter","Shift + Enter","Alt + Enter","Ctrl + Shift + Enter"],"answer":0,"explanation":"Ctrl + Enter starts a new page. Shift + Enter inserts only a line break within the same paragraph, and Ctrl + Shift + Enter inserts a column break.","difficulty":"easy","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-42","question":"In MS PowerPoint, which shortcut adds a new slide to the presentation?","options":["Ctrl + D","Ctrl + N","Ctrl + S","Ctrl + M"],"answer":3,"explanation":"Ctrl + M inserts a new slide. Ctrl + N opens a new presentation, Ctrl + S saves and Ctrl + D duplicates the selected slide or object.","difficulty":"easy","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-43","question":"In MS Excel, which function key lets you edit the contents of the active cell directly?","options":["F7","F4","F2","F12"],"answer":2,"explanation":"F2 puts the active cell into edit mode. F4 repeats the last action or toggles references, F7 runs spell-check and F12 opens Save As.","difficulty":"easy","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-44","question":"In a web address such as https://www.example.gov.in, the part '.in' is the:","options":["Protocol","Country-code top-level domain","Sub-domain","File path"],"answer":1,"explanation":".in is India's country-code top-level domain (ccTLD). 'https' is the protocol and 'www' is a sub-domain; there is no path in this address.","difficulty":"easy","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-45","question":"The HTTP status code shown when the requested web page does not exist on the server is:","options":["500","200","301","404"],"answer":3,"explanation":"404 means Not Found. 200 means OK (success), 301 means the page has moved permanently, and 500 is an internal server error.","difficulty":"easy","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-46","question":"Which view in MS PowerPoint shows thumbnails of all slides together so that they can be rearranged easily?","options":["Slide Sorter view","Notes Page view","Reading view","Outline view"],"answer":0,"explanation":"Slide Sorter displays every slide as a thumbnail for reordering, deleting or duplicating. Notes Page shows one slide with its speaker notes; Reading view plays the show in a window.","difficulty":"easy","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-47","question":"Which of the following is an example of 'something you are' in authentication?","options":["OTP received on mobile","Password","Fingerprint scan","Smart card"],"answer":2,"explanation":"Biometrics like fingerprints are inherence factors ('something you are'). A password is something you know; an OTP device and a smart card are something you have.","difficulty":"easy","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-48","question":"In MS Excel, which shortcut inserts the current date in the active cell?","options":["Ctrl + Shift + ;","Ctrl + ;","Ctrl + D","Alt + ;"],"answer":1,"explanation":"Ctrl + ; enters today's date as a fixed value. Ctrl + Shift + ; enters the current time, and Ctrl + D fills down.","difficulty":"easy","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-49","question":"Which national helpline number can a victim of online financial fraud in India dial to report it?","options":["100","1930","1098","112"],"answer":1,"explanation":"1930 is the national cyber crime helpline for reporting financial cyber fraud (complaints can also be lodged on cybercrime.gov.in). 1098 is Childline and 112 is the general emergency number.","difficulty":"easy","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-50","question":"Which feature of MS Word combines a standard letter with a list of names and addresses to create personalised copies?","options":["Thesaurus","Track Changes","Macro","Mail Merge"],"answer":3,"explanation":"Mail Merge joins a main document with a data source (such as an Excel list). Track Changes records edits, and a macro automates repeated tasks.","difficulty":"easy","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-51","question":"The protocol whose default port number is 22 and which provides secure remote login is:","options":["SSH","Telnet","FTP","SMTP"],"answer":0,"explanation":"SSH runs on port 22 and encrypts the session. Telnet (port 23) does a similar job but sends everything, including passwords, in plain text.","difficulty":"easy","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-52","question":"In MS Word, what does the shortcut Shift + F3 do to selected text?","options":["Applies strikethrough","Opens the Find dialog","Changes its case, cycling through lowercase, UPPERCASE and Capitalise Each Word","Opens the thesaurus"],"answer":2,"explanation":"Shift + F3 cycles the case of the selection. Shift + F7 opens the thesaurus and Ctrl + F opens Find.","difficulty":"moderate","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-53","question":"In MS Word, which shortcut makes the selected text subscript (as in H₂O)?","options":["Ctrl + Shift + S","Ctrl + Shift + =","Ctrl + ]","Ctrl + ="],"answer":3,"explanation":"Ctrl + = toggles subscript; Ctrl + Shift + = (that is, Ctrl + +) toggles superscript. Ctrl + ] increases the font size by one point.","difficulty":"moderate","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-54","question":"In MS Word, which shortcut sets 1.5 line spacing for the selected paragraph?","options":["Ctrl + 5","Ctrl + 1","Ctrl + 2","Ctrl + 3"],"answer":0,"explanation":"Ctrl + 1 gives single spacing, Ctrl + 2 double spacing and Ctrl + 5 gives 1.5 line spacing. Ctrl + 3 is not a line-spacing shortcut.","difficulty":"moderate","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-55","question":"During a PowerPoint slide show, pressing the 'B' key:","options":["Bolds the text on the current slide","Jumps back to the first slide","Turns the screen black; pressing it again returns to the show","Ends the slide show"],"answer":2,"explanation":"B (or the full stop key) blacks out the screen and W (or comma) whitens it; pressing the key again resumes. Esc ends the show; Home goes to the first slide.","difficulty":"moderate","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-56","question":"In MS PowerPoint, which shortcut starts the slide show from the CURRENT slide rather than from the first?","options":["F5","Shift + F5","Ctrl + F5","Alt + F5"],"answer":1,"explanation":"Shift + F5 starts from the selected slide; F5 always starts from slide 1.","difficulty":"moderate","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-57","question":"In MS Excel, which shortcut turns AutoFilter on or off for the selected data range?","options":["Ctrl + Shift + L","Ctrl + Shift + F","Alt + F","Ctrl + L"],"answer":0,"explanation":"Ctrl + Shift + L toggles the filter dropdowns. Ctrl + L (like Ctrl + T) creates a table, which also adds filters, but it does not toggle them off.","difficulty":"moderate","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-58","question":"In MS Excel, pressing Alt + = in the cell below a column of numbers:","options":["Opens the Insert Function dialog","Inserts the AutoSum (SUM) formula for the numbers above","Shows all formulas instead of values","Copies the formula from the cell above"],"answer":1,"explanation":"Alt + = inserts =SUM() over the adjacent range. Shift + F3 opens Insert Function, Ctrl + ` shows formulas, and Ctrl + D copies the cell above.","difficulty":"moderate","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-59","question":"In MS Excel, which shortcut opens the Format Cells dialog box?","options":["Ctrl + Shift + F1","Ctrl + F","Ctrl + 1","Alt + 1"],"answer":2,"explanation":"Ctrl + 1 opens Format Cells (number, alignment, font, border, fill, protection). Ctrl + F opens Find.","difficulty":"moderate","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-60","question":"In MS Excel, how do you start a new line of text inside the same cell?","options":["Tab","Shift + Enter","Ctrl + Enter","Alt + Enter"],"answer":3,"explanation":"Alt + Enter inserts a line break within a cell. Shift + Enter moves to the cell above, and Ctrl + Enter enters the same data in all selected cells.","difficulty":"moderate","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-61","question":"What does the Excel formula =ROUND(1234.567, -2) return?","options":["1200","1234.57","1234.6","1300"],"answer":0,"explanation":"A negative second argument rounds to the left of the decimal point: -2 rounds to the nearest hundred, giving 1200. 1234.57 would need 2 as the argument.","difficulty":"moderate","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-62","question":"What does the Excel formula =MID(\"COMPUTER\", 3, 4) return?","options":["OMPU","MPUT","MPUTE","PUTE"],"answer":1,"explanation":"MID takes 4 characters starting at position 3: C(1) O(2) M(3) P(4) U(5) T(6) → MPUT.","difficulty":"moderate","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-63","question":"In Excel, A1:A6 contain 45, 60, 75, 50, 90 and 30. What does =COUNTIF(A1:A6, \">50\") return?","options":["5","4","2","3"],"answer":3,"explanation":"Values strictly greater than 50 are 60, 75 and 90 → 3. The value 50 itself is not included; that would need \">=50\", which gives 4.","difficulty":"moderate","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-64","question":"Which Excel 'What-If Analysis' tool finds the input value needed to make a formula reach a desired result?","options":["Data Validation","Scenario Manager","Goal Seek","Consolidate"],"answer":2,"explanation":"Goal Seek works backwards: you give the target result and the cell to change, and it finds the input. Scenario Manager compares several saved sets of inputs; Data Validation restricts entries.","difficulty":"moderate","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-65","question":"The Excel feature that keeps the top row or first column visible while you scroll through a large sheet is:","options":["Freeze Panes","Split Cells","Wrap Text","Group"],"answer":0,"explanation":"View → Freeze Panes locks rows/columns in place. Wrap Text only fits text within a cell, and Group collapses rows or columns.","difficulty":"moderate","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-66","question":"A PowerPoint file saved with the extension .ppsx:","options":["Contains macros","Is a PowerPoint template","Opens directly as a slide show when double-clicked","Can be opened only in PowerPoint 2003"],"answer":2,"explanation":".ppsx is a PowerPoint Show and opens straight into slide-show mode. A template is .potx, and a macro-enabled presentation is .pptm.","difficulty":"moderate","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-67","question":"In PowerPoint, which feature lets you change the font, colours and logo of ALL slides in one place?","options":["Custom Slide Show","Slide Sorter","Rehearse Timings","Slide Master"],"answer":3,"explanation":"Editing the Slide Master changes every slide based on its layouts. Slide Sorter only reorders slides; Rehearse Timings records how long each slide is shown.","difficulty":"moderate","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-68","question":"Which default port does the POP3 protocol use for downloading e-mail?","options":["143","110","25","993"],"answer":1,"explanation":"POP3 uses port 110. IMAP uses 143, SMTP uses 25 for sending, and 993 is IMAP over SSL/TLS.","difficulty":"moderate","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-69","question":"An attacker redirects users who type a genuine bank's address to a fake look-alike site by corrupting DNS records. This attack is called:","options":["Spamming","Phishing","Pharming","Spoofing of caller ID"],"answer":2,"explanation":"Pharming poisons DNS or the hosts file so even a correctly typed address leads to the fake site. Phishing relies on luring the victim to click a link, usually in an e-mail.","difficulty":"moderate","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-70","question":"A phishing attack aimed specifically at top executives such as a CEO or CFO is known as:","options":["Baiting","Vishing","Smishing","Whaling"],"answer":3,"explanation":"Whaling targets 'big fish' — senior executives. Vishing uses voice calls and smishing uses SMS; baiting leaves infected devices or tempting downloads for victims.","difficulty":"moderate","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-71","question":"Malicious code planted in a program that stays dormant and activates only when a particular condition is met (such as a specific date) is a:","options":["Logic bomb","Worm","Adware","Botnet"],"answer":0,"explanation":"A logic bomb is triggered by a condition or date. A worm spreads by itself across networks, and a botnet is a network of compromised computers controlled remotely.","difficulty":"moderate","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-72","question":"Under the Information Technology Act, 2000, identity theft — fraudulently using another person's password, electronic signature or other unique identification — is punishable under:","options":["Section 66A","Section 66C","Section 67","Section 43A"],"answer":1,"explanation":"Section 66C deals with identity theft. Section 66A was struck down by the Supreme Court in 2015; Section 67 concerns obscene material, and 43A covers compensation for failure to protect data.","difficulty":"moderate","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-73","question":"Charging a phone at an infected public USB charging port, which secretly steals data or installs malware, is called:","options":["Shoulder surfing","Juice jacking","Tailgating","Clickjacking"],"answer":1,"explanation":"Juice jacking abuses the data lines of a USB port. Shoulder surfing is watching someone type a PIN, tailgating is following an authorised person through a secure door, and clickjacking tricks users into clicking hidden page elements.","difficulty":"moderate","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-74","question":"What does the Excel formula =-2^2 return?","options":["4","-4","0","#VALUE!"],"answer":0,"explanation":"In Excel, negation has higher precedence than exponentiation, so it is evaluated as (-2)^2 = 4. In ordinary algebra (and in many programming languages) -2² would be -4, which is the trap.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-75","question":"What does the Excel formula =2^3^2 return?","options":["36","512","12","64"],"answer":3,"explanation":"Excel evaluates operators of equal precedence from left to right: (2^3)^2 = 8^2 = 64. Mathematical convention (right-to-left) would give 2^9 = 512.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-76","question":"What does the Excel formula =MOD(-7, 3) return?","options":["1","-1","2","-2"],"answer":2,"explanation":"Excel's MOD returns a result with the same sign as the divisor: MOD(n, d) = n − d × INT(n/d) = −7 − 3 × (−3) = 2. -1 is what truncating division (as in C or Java's %) gives.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-77","question":"What does the Excel formula =TRUNC(-4.7) return?","options":["-4.7","-5","-4","4"],"answer":2,"explanation":"TRUNC simply removes the decimal part, giving -4. INT rounds down to the next lower integer, so INT(-4.7) would be -5 — the tempting choice.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-78","question":"What does the Excel formula =ROUNDUP(-3.21, 1) return?","options":["-3.3","-3.2","-3.21","-4"],"answer":0,"explanation":"ROUNDUP always rounds away from zero, so -3.21 becomes -3.3. Rounding 'up' towards the larger value -3.2 is the trap.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-79","question":"What does the Excel formula =LEN(TRIM(\"  Data   Entry  \")) return?","options":["9","16","12","10"],"answer":3,"explanation":"TRIM removes leading and trailing spaces and reduces internal runs of spaces to a single space, leaving \"Data Entry\" — 10 characters including the one space.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-80","question":"What does the Excel formula =10-2^2*3 return?","options":["24","-2","192","4"],"answer":1,"explanation":"Order: exponent first (2^2 = 4), then multiplication (4 × 3 = 12), then subtraction (10 − 12 = −2). Working left to right without precedence gives 192.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-81","question":"In Excel, A1:A6 contain 45, 60, 75, 50, 90 and 30. What does =SUMIF(A1:A6, \">=50\") return?","options":["225","275","320","350"],"answer":1,"explanation":"Values ≥ 50 are 60, 75, 50 and 90; their sum is 275. Excluding 50 (i.e. \">50\") gives 225.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-82","question":"In Excel, A1:A6 contain 45, 60, 75, 50, 90 and 30. What does =AVERAGEIF(A1:A6, \">40\") return?","options":["75","58.33","64","53.33"],"answer":2,"explanation":"Values greater than 40: 45, 60, 75, 50, 90 → sum 320 ÷ 5 = 64. 58.33 is the plain average of all six values (350 ÷ 6).","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-83","question":"In Excel, A1:A4 contain 0, 40, 60, 80 and B1:B4 contain the grades F, C, B, A. What does =VLOOKUP(73, A1:B4, 2, TRUE) return?","options":["#N/A","A","C","B"],"answer":3,"explanation":"With TRUE (approximate match) VLOOKUP finds the largest value ≤ 73 in the sorted first column, which is 60, and returns its grade B. #N/A would come only with an exact match (FALSE).","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-84","question":"What does the Excel formula =MATCH(25, {10,20,30,40}, 1) return?","options":["2","3","#N/A","25"],"answer":0,"explanation":"Match type 1 returns the position of the largest value less than or equal to 25 in an ascending list — 20, at position 2. MATCH returns a position, not the value.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-85","question":"What does the Excel formula =LARGE({12,45,7,45,30}, 2) return?","options":["45","30","12","7"],"answer":0,"explanation":"LARGE counts duplicates separately: sorted descending the list is 45, 45, 30, 12, 7, so the 2nd largest is 45. Choosing 30 assumes duplicates are ignored.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-86","question":"What does the Excel formula =SUMPRODUCT({2,3,1}, {4,5,6}) return?","options":["120","21","29","15"],"answer":2,"explanation":"SUMPRODUCT multiplies corresponding items and adds: 2×4 + 3×5 + 1×6 = 8 + 15 + 6 = 29. 21 is simply the total of all six numbers.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-87","question":"In Excel, A1 contains the date 01-01-2024 and B1 contains 01-03-2024 (1 March 2024). What does =B1-A1 return?","options":["59","60","2","61"],"answer":1,"explanation":"Excel stores dates as serial numbers, so subtraction gives the days between them: 31 (January) + 29 (February in the leap year 2024) = 60. 59 assumes a 28-day February.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-88","question":"The Excel formula =A1+$B$1 is in cell C1. If it is copied to cell D3, it becomes:","options":["=A3+$B$1","=A1+$B$1","=B3+$C$3","=B3+$B$1"],"answer":3,"explanation":"The relative part shifts one column right and two rows down (A1 → B3); the absolute reference $B$1 does not change.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-89","question":"In Excel, pressing F4 repeatedly while the cursor is on the reference A1 in a formula cycles it through which sequence?","options":["A$1 → $A1 → $A$1 → A1","$A$1 → A$1 → $A1 → A1","$A1 → A$1 → $A$1 → A1","$A$1 → $A1 → A$1 → A1"],"answer":1,"explanation":"F4 first makes the reference fully absolute ($A$1), then locks only the row (A$1), then only the column ($A1), and finally returns to relative (A1).","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-90","question":"In Excel 2007 and later, how many rows and columns does a worksheet have?","options":["1,048,576 rows and 16,384 columns","65,536 rows and 256 columns","1,048,576 rows and 256 columns","16,384 rows and 1,048,576 columns"],"answer":0,"explanation":"Since Excel 2007 a sheet has 2²⁰ = 1,048,576 rows and 2¹⁴ = 16,384 columns (A to XFD). 65,536 × 256 was the limit in Excel 2003 and earlier.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-91","question":"Which Excel error value appears when a formula refers to a cell that has been deleted?","options":["#N/A","#NAME?","#REF!","#NULL!"],"answer":2,"explanation":"#REF! signals an invalid cell reference, typically after deleting rows, columns or cells used by a formula. #NAME? means Excel does not recognise a name or function.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-92","question":"In Excel, typing =SUMM(A1:A5) by mistake produces which error?","options":["#N/A","#VALUE!","#REF!","#NAME?"],"answer":3,"explanation":"Excel does not recognise the function name SUMM, so it shows #NAME?. #VALUE! arises from a wrong type of argument, such as adding text to a number.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-93","question":"In Excel, the shortcut Ctrl + ` (grave accent) is used to:","options":["Copy the value from the cell above","Insert the current time","Toggle between showing formulas and showing their results","Open the Visual Basic editor"],"answer":2,"explanation":"Ctrl + ` switches the sheet to formula view and back. Ctrl + Shift + ; inserts the time, Ctrl + ' copies the formula from the cell above, and Alt + F11 opens the VBA editor.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-94","question":"In Excel, pressing F11 with data selected:","options":["Recalculates all formulas","Inserts a new worksheet","Creates an embedded chart on the same sheet","Creates a default chart on a new chart sheet"],"answer":3,"explanation":"F11 makes a chart on a separate chart sheet; Alt + F1 makes an embedded chart on the current sheet. Shift + F11 inserts a new worksheet and F9 recalculates.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-95","question":"In Excel 2013 and later, which shortcut runs Flash Fill to complete a column based on a pattern you have typed?","options":["Ctrl + F","Ctrl + E","Ctrl + R","Ctrl + Shift + E"],"answer":1,"explanation":"Ctrl + E triggers Flash Fill. Ctrl + R fills right (copies the cell on the left), and Ctrl + F opens Find.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-96","question":"In MS Word, which shortcut inserts a footnote at the cursor position?","options":["Ctrl + Alt + F","Ctrl + Alt + D","Ctrl + Alt + M","Ctrl + Shift + F"],"answer":0,"explanation":"Ctrl + Alt + F inserts a footnote and Ctrl + Alt + D an endnote. Ctrl + Alt + M inserts a comment.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-97","question":"In MS Word, Ctrl + Shift + C followed by Ctrl + Shift + V on other text is used to:","options":["Count characters and paste the count","Copy and paste text without formatting","Insert a copyright symbol","Copy and paste only the formatting, like Format Painter"],"answer":3,"explanation":"Ctrl + Shift + C copies formatting and Ctrl + Shift + V applies it — the keyboard version of Format Painter. It does not copy the text itself.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-98","question":"In MS Word, which shortcut turns Track Changes on or off?","options":["Ctrl + Shift + E","Ctrl + Shift + T","Ctrl + Alt + T","Ctrl + T"],"answer":0,"explanation":"Ctrl + Shift + E toggles Track Changes. Ctrl + T creates a hanging indent and Ctrl + Shift + T removes it.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-99","question":"In MS Word, Ctrl + Backspace deletes:","options":["The whole current line","The word to the left of the cursor","The character to the right of the cursor","The whole paragraph"],"answer":1,"explanation":"Ctrl + Backspace deletes the previous word and Ctrl + Delete the next word. Plain Delete removes one character to the right.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-100","question":"In MS Word, the 'gutter' margin is:","options":["The space reserved for headers and footers","The space between two columns of text","Extra space added to a margin to allow for binding","The blank area at the end of the last page"],"answer":2,"explanation":"A gutter adds space to the side or top margin so text is not hidden by binding. The space between columns is simply the column spacing.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-101","question":"The Word paragraph option 'Widow/Orphan control' prevents:","options":["A single line of a paragraph being left alone at the top or bottom of a page","Text from wrapping around pictures","Hyphenation of long words","Headings from appearing in the table of contents"],"answer":0,"explanation":"With widow/orphan control on, Word will not leave the last line of a paragraph alone at the top of a page (widow) or its first line alone at the bottom (orphan).","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-102","question":"A Word document that contains macros must be saved with which extension to keep them?","options":[".dotx",".docx",".docm",".rtf"],"answer":2,"explanation":".docm is the macro-enabled document format. .docx cannot store macros, .dotx is a macro-free template and .rtf is Rich Text Format.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-103","question":"In a URL such as https://shop.example.com/items/list.html?page=2#reviews, the part 'page=2' is the:","options":["Fragment","Query string","Path","Host name"],"answer":1,"explanation":"Everything after '?' is the query string (here page=2). '#reviews' is the fragment, '/items/list.html' is the path, and shop.example.com is the host name.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-104","question":"Which protocol finds the MAC (hardware) address of a device on a local network when its IP address is known?","options":["ICMP","DHCP","DNS","ARP"],"answer":3,"explanation":"ARP (Address Resolution Protocol) maps an IPv4 address to a MAC address. DNS maps domain names to IP addresses and DHCP assigns IP addresses; ICMP carries error messages such as ping.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-105","question":"Which technology lets many devices on a home network with private IP addresses share a single public IP address on the internet?","options":["NAT (Network Address Translation)","DNS","FTP","VLAN"],"answer":0,"explanation":"NAT on the router rewrites private source addresses to its one public address and tracks the replies. DNS only resolves names to addresses.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-106","question":"In a Google search, which query restricts results to PDF documents from Indian government websites about 'digital literacy'?","options":["digital literacy site:pdf filetype:gov.in","digital literacy +pdf -gov.in","\"digital literacy\" OR pdf OR gov.in","digital literacy filetype:pdf site:gov.in"],"answer":3,"explanation":"filetype: limits the file format and site: limits the domain. The last option swaps the two operators, and '-gov.in' would exclude government sites.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-107","question":"Which part of the CIA triad of information security is the main target of a Distributed Denial-of-Service (DDoS) attack?","options":["Confidentiality","Availability","Integrity","Authenticity"],"answer":1,"explanation":"A DDoS floods a server with traffic so that legitimate users cannot reach it — an attack on availability. It does not usually steal (confidentiality) or alter (integrity) data.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-108","question":"An attacker types ' OR '1'='1 into a website's login box to bypass the password check. This is an example of:","options":["Brute-force attack","Cross-site scripting","SQL injection","Buffer overflow"],"answer":2,"explanation":"Inserting SQL code into an input field to alter the database query is SQL injection. Cross-site scripting injects scripts into web pages viewed by other users; brute force tries many passwords.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-109","question":"A network of computers infected with malware and controlled remotely by an attacker, often used to send spam or launch DDoS attacks, is called a:","options":["Honeypot","Botnet","Intranet","Firewall"],"answer":1,"explanation":"Each infected machine is a 'bot' or 'zombie'; together they form a botnet. A honeypot is a decoy system set up by defenders to attract attackers.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-110","question":"A security flaw that is exploited by attackers before the software vendor has released any fix for it is called a:","options":["Zero-day vulnerability","Backdoor","Patch","False positive"],"answer":0,"explanation":"'Zero-day' means the vendor has had zero days to fix it. A patch is the fix itself; a backdoor is a hidden way of bypassing authentication.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-111","question":"Which of these encryption algorithms is asymmetric, using a public key and a private key?","options":["Triple DES","AES","DES","RSA"],"answer":3,"explanation":"RSA is a public-key (asymmetric) algorithm. AES, DES and 3DES are symmetric: the same secret key encrypts and decrypts.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-112","question":"Which of the following pairs of factors gives genuine two-factor authentication?","options":["A PIN and a password","A password and a security question","A password and an OTP sent to the registered mobile","A fingerprint and a face scan"],"answer":2,"explanation":"Two-factor authentication needs factors of two different kinds — here something you know (password) and something you have (phone). Password + security question or PIN + password are both 'something you know'; fingerprint + face are both 'something you are'.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-113","question":"In Excel, the divisor is negative in =MOD(7, -3). What result does the formula give?","options":["1","-2","-1","2"],"answer":1,"explanation":"MOD(n, d) = n − d × INT(n/d) = 7 − (−3) × INT(−2.33) = 7 − (−3)(−3) = 7 − 9 = −2. The result takes the sign of the divisor, so the positive answers are traps.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-114","question":"What does the Excel formula =ROUNDDOWN(-3.78, 1) return?","options":["-4","-3.8","-3.7","-3.78"],"answer":2,"explanation":"ROUNDDOWN always rounds towards zero, so -3.78 becomes -3.7. 'Down' in the sense of a smaller number (-3.8) is the trap; FLOOR-style rounding would give that.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-115","question":"What does the Excel formula =ROUND(1250, -2) return?","options":["1300","1200","1250","1000"],"answer":0,"explanation":"Rounding to the nearest hundred, 1250 is exactly halfway; Excel's ROUND rounds halves away from zero, so the result is 1300. 1200 assumes 'round half to even' (banker's rounding), which Excel's ROUND does not use.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-116","question":"What does the Excel formula =-3^2+1 return?","options":["8","-8","-10","10"],"answer":3,"explanation":"Negation is applied before the exponent in Excel: (-3)^2 + 1 = 9 + 1 = 10. Treating it as -(3^2) + 1 gives -8, the algebra-textbook answer.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-117","question":"What does the Excel formula =\"A\"&1+2 return?","options":["A12","A3","#VALUE!","A1+2"],"answer":1,"explanation":"Arithmetic operators rank above the concatenation operator &, so 1+2 is worked out first and then joined: \"A\" & 3 = \"A3\". 'A12' would need brackets: =(\"A\"&1)&2.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-118","question":"What does the Excel formula =FIND(\"N\", \"Banana\") return?","options":["#N/A","3","0","#VALUE!"],"answer":3,"explanation":"FIND is case-sensitive, and \"Banana\" has no capital N, so it returns #VALUE!. SEARCH, which ignores case, would return 3.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-119","question":"What does the Excel formula =SEARCH(\"N\", \"Banana\") return?","options":["3","#VALUE!","5","2"],"answer":0,"explanation":"SEARCH is not case-sensitive, so it finds the first 'n' at position 3 (B-a-n). FIND would have failed with #VALUE! because it is case-sensitive.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-120","question":"In Excel, A1 = 5, A2 contains the TEXT \"7\" (entered as text), A3 = TRUE, A4 is blank and A5 = 3. What does =COUNT(A1:A5) return?","options":["4","3","2","5"],"answer":2,"explanation":"COUNT counts only numeric cells in a range: 5 and 3. Numbers stored as text and logical values inside a range are ignored, so 3 or 4 are traps; COUNTA would return 4.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-121","question":"In Excel, A1 = 5 and A2 contains the text \"7\" (a number stored as text). What do =SUM(A1:A2) and =A1+A2 return respectively?","options":["12 and 5","12 and 12","5 and #VALUE!","5 and 12"],"answer":3,"explanation":"SUM over a range ignores text, giving 5. But the + operator converts numeric text into a number, so =A1+A2 gives 12.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-122","question":"In Excel, A1:A4 contain 1, 2, 3 and 4. What does =SUM(A1:A3,A2:A4) return?","options":["10","15","5","9"],"answer":1,"explanation":"The comma is the union operator, so both ranges are added in full and the overlapping cells A2 and A3 count twice: (1+2+3) + (2+3+4) = 15. 10 assumes the overlap is counted once.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-123","question":"In Excel, A1:A4 contain 1, 2, 3 and 4. What does =SUM(A1:A3 A2:A4) return (note the space between the ranges)?","options":["10","15","5","#NULL!"],"answer":2,"explanation":"A space is Excel's intersection operator; the ranges overlap in A2:A3, so the result is 2 + 3 = 5. #NULL! would appear only if the ranges did not overlap at all.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-124","question":"Which Excel error value appears for =SUM(A1:A3 C1:C3)?","options":["#NULL!","#REF!","#VALUE!","#N/A"],"answer":0,"explanation":"The space between the ranges is the intersection operator, and A1:A3 and C1:C3 share no cell, so Excel returns #NULL!.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-125","question":"The formula =$A1*B$2 is in cell C3. When it is copied to cell E5, it becomes:","options":["=$A3*D$2","=$A1*D$2","=$C3*D$4","=$A3*B$4"],"answer":0,"explanation":"Moving two columns right and two rows down: in $A1 the column is locked and the row changes (1 → 3); in B$2 the row is locked and the column changes (B → D).","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-126","question":"What does the Excel formula =DATE(2024, 2, 30) return?","options":["2 March 2024","#NUM!","29 February 2024","1 March 2024"],"answer":3,"explanation":"DATE rolls extra days over into the next month. February 2024 has 29 days (leap year), so day 30 becomes 1 March 2024. 2 March would be correct for a non-leap year.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-127","question":"What does the Excel formula =DATE(2023, 13, 1) return?","options":["1 December 2023","#NUM!","1 January 2024","13 January 2023"],"answer":2,"explanation":"A month number above 12 rolls over into the next year: month 13 of 2023 is January 2024. Excel does not raise an error for it.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-128","question":"In Excel, the column immediately after column AZ is BA. What is the column number of AZ, and which column is number 100?","options":["52; CU","52; CV","51; CV","78; DV"],"answer":1,"explanation":"AZ = 1×26 + 26 = 52. For 100: 100 = 3×26 + 22, i.e. third letter C and 22nd letter V → CV.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-129","question":"In Excel, A1 = 75. What does =IF(A1>=40, IF(A1>=75, \"Distinction\", \"Pass\"), \"Fail\") return?","options":["FALSE","Pass","Fail","Distinction"],"answer":3,"explanation":"75 ≥ 40 is TRUE, so the inner IF runs; 75 ≥ 75 is also TRUE (the test is 'greater than or equal'), giving \"Distinction\". Reading >= as > leads to the trap \"Pass\".","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-130","question":"In Excel, A2:A5 contain the names Asha, Ravi, Meena, Tarun and B2:B5 contain 82, 67, 91, 74. What does =INDEX(B2:B5, MATCH(\"Meena\", A2:A5, 0)) return?","options":["67","3","91","Meena"],"answer":2,"explanation":"MATCH finds \"Meena\" at position 3 of A2:A5 (exact match, type 0), and INDEX returns the 3rd value of B2:B5, which is 91. 3 is only MATCH's output.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-131","question":"In Excel, A1 = 0.256. What does =TEXT(A1, \"0.0%\") return?","options":["0.3%","25.6%","26%","2.6%"],"answer":1,"explanation":"The % in the format code multiplies the value by 100 and adds a percent sign; \"0.0\" keeps one decimal place: 25.6%. Ignoring the multiplication gives 0.3%.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-132","question":"In Excel, what does =IFERROR(1/0, \"Check\") & \"!\" return?","options":["Check!","#DIV/0!","#DIV/0!!","Check"],"answer":0,"explanation":"1/0 is an error, so IFERROR returns \"Check\"; the & operator then joins \"!\" to give \"Check!\".","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-133","question":"Which of the following Excel formulas does NOT return an error?","options":["=\"5\"*2","=\"abc\"*2","=SQRT(-4)","=VLOOKUP(99,{1,\"a\";2,\"b\"},2,FALSE)"],"answer":0,"explanation":"\"5\"*2 converts the numeric text to 5 and returns 10. \"abc\"*2 gives #VALUE!, SQRT of a negative number gives #NUM!, and an exact-match VLOOKUP that finds nothing gives #N/A.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-134","question":"The same key combination does different things in different Office programs. What does Ctrl + D do in MS Word, MS Excel and MS PowerPoint respectively?","options":["Fills down; opens the Font dialog; deletes the slide","Opens the Font dialog; fills down; duplicates the selected slide or object","Duplicates; fills down; opens the Font dialog","Opens the Font dialog; deletes the row; duplicates the slide"],"answer":1,"explanation":"In Word, Ctrl + D opens the Font dialog; in Excel it copies the top cell of a selection down (Fill Down); in PowerPoint it duplicates the selected slide or object.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-135","question":"In MS Word, which pair of shortcuts increases and decreases the font size of the selected text by exactly 1 point?","options":["Alt + ] and Alt + [","Ctrl + Shift + > and Ctrl + Shift + <","Ctrl + + and Ctrl + -","Ctrl + ] and Ctrl + ["],"answer":3,"explanation":"Ctrl + ] and Ctrl + [ change the size by one point. Ctrl + Shift + > and < jump to the next or previous size in the font-size list (e.g. 12 → 14), which is the trap.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-136","question":"In MS Word, Shift + Enter, Ctrl + Enter and Ctrl + Shift + Enter insert, respectively:","options":["A column break, a page break and a line break","A page break, a line break and a section break","A line break, a page break and a column break","A paragraph break, a column break and a page break"],"answer":2,"explanation":"Shift + Enter = manual line break (same paragraph); Ctrl + Enter = page break; Ctrl + Shift + Enter = column break.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-137","question":"In MS Word, which type of section break should be used to change from one-column to two-column layout in the middle of a page, without starting a new page?","options":["Continuous","Next Page","Even Page","Odd Page"],"answer":0,"explanation":"A Continuous section break starts a new section on the same page, so the column layout can change mid-page. Next Page, Even Page and Odd Page breaks all force the new section onto another page.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-138","question":"In Word's Mail Merge, which statement is correct?","options":["Merge fields are typed manually as plain text between angle brackets","The data source must be another Word document; Excel lists cannot be used","The main document holds the fixed text and merge fields, while the data source supplies the values that change for each recipient","Mail Merge can only produce letters, not envelopes or labels"],"answer":2,"explanation":"The main document contains constant text plus merge fields; the data source (Excel sheet, Access table, Outlook contacts or a Word table) holds the variable data. Typing «Name» by hand does not create a working field, and Mail Merge can also make envelopes, labels and e-mails.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-139","question":"During a PowerPoint slide show, what happens when you type 7 and then press Enter?","options":["The show advances seven slides","The show jumps directly to slide 7","The pen colour changes","The screen zooms to 70%"],"answer":1,"explanation":"Typing a slide number and pressing Enter jumps straight to that slide. Ctrl + P switches the pointer to a pen during a show.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-140","question":"Which statement about PowerPoint transitions and animations is correct?","options":["Animations can be added only in Slide Master view","A transition applies to text boxes and an animation to whole slides","Both terms mean the same effect","A transition is an effect applied when moving from one slide to the next; an animation is applied to an object within a slide"],"answer":3,"explanation":"Transitions work between slides; animations make individual objects (text, pictures, charts) enter, exit or move. They are set from separate tabs.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-141","question":"Match the protocol with its default port: 1. Telnet 2. IMAP 3. POP3 over SSL (POP3S) 4. RDP; a. 3389 b. 995 c. 23 d. 143","options":["1-d, 2-c, 3-b, 4-a","1-c, 2-b, 3-d, 4-a","1-c, 2-d, 3-b, 4-a","1-c, 2-d, 3-a, 4-b"],"answer":2,"explanation":"Telnet uses 23, IMAP 143, POP3S 995 and Remote Desktop Protocol 3389. Note that IMAPS (993) and POP3S (995) are easily confused.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-142","question":"Ignoring overheads, roughly how long will it take to download a 1 GB file (1 GB = 1024 MB) on a 20 Mbps connection?","options":["About 6.8 minutes","About 51 seconds","About 3.4 minutes","About 54 minutes"],"answer":0,"explanation":"1 GB = 1024 MB × 8 = 8192 megabits; 8192 ÷ 20 = 409.6 seconds ≈ 6.8 minutes. 51 seconds forgets to convert bytes into bits.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-143","question":"Ravi wants to send a confidential file to Neha using public-key cryptography so that only Neha can read it. Which key should be used to encrypt the file?","options":["Neha's private key","Ravi's public key","Ravi's private key","Neha's public key"],"answer":3,"explanation":"For confidentiality, encrypt with the recipient's public key; only the recipient's private key can decrypt it. Encrypting with Ravi's private key is how a digital signature is made — it proves origin but anyone with Ravi's public key can read it.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-144","question":"To verify the digital signature on a document signed by a bank, the receiver uses:","options":["The bank's private key","The bank's public key","The receiver's private key","A shared secret password"],"answer":1,"explanation":"A signature is created with the signer's private key and verified with the signer's public key, usually obtained from a digital certificate issued by a Certifying Authority. The private key is never shared.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-145","question":"How many hexadecimal characters long is a SHA-256 hash value when written out?","options":["32","64","256","128"],"answer":1,"explanation":"SHA-256 produces a 256-bit digest; each hex character represents 4 bits, so 256 ÷ 4 = 64 characters. 32 hex characters is the length of an MD5 (128-bit) hash.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-146","question":"How many of these statements about HTTPS are correct? I. It uses TLS to encrypt data between browser and server. II. Its default port is 443. III. The padlock icon proves the website belongs to a trustworthy organisation. IV. It hides the website address from the user's internet service provider.","options":["Only two","Only three","Only one","All four"],"answer":0,"explanation":"I and II are correct. III is wrong — the padlock only shows an encrypted connection with a valid certificate; phishing sites can have one too. IV is wrong — the ISP can still see which domain is visited (through DNS and the TLS handshake), even if not the page content.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-147","question":"How many of these statements about browsing are correct? I. A private/incognito window does not save history or cookies after it is closed. II. Incognito mode hides your browsing from your employer's network. III. Third-party cookies are commonly used for cross-site ad tracking. IV. Clearing the browser cache removes saved copies of web pages and images.","options":["All four","Only two","Only three","Only one"],"answer":2,"explanation":"I, III and IV are correct. II is wrong: incognito mode only avoids storing data on the local device; the network administrator, ISP and the visited websites can still see the traffic.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-148","question":"Under the IT Act, 2000, which section prescribes punishment that may extend to imprisonment for life for cyber terrorism?","options":["Section 43","Section 66C","Section 66D","Section 66F"],"answer":3,"explanation":"Section 66F covers cyber terrorism, punishable with imprisonment up to life. 66C is identity theft and 66D cheating by personation using a computer resource; Section 43 provides compensation (a civil remedy), not imprisonment.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-149","question":"A fraudster convinces a mobile operator to issue a new SIM for a victim's number, then uses the OTPs received on it to empty the victim's bank account. This is known as:","options":["SIM swap fraud","Vishing","Juice jacking","Pharming"],"answer":0,"explanation":"In SIM swap (SIM cloning) fraud the criminal takes control of the victim's number, so bank OTPs reach him. Vishing is fraud by phone call and needs the victim to reveal details; juice jacking uses USB charging ports.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-ms-office-internet-150","question":"Assertion (A): A firewall alone cannot protect a user who opens a malicious e-mail attachment. Reason (R): A firewall filters network traffic by rules, but the attachment arrives through permitted e-mail traffic and runs on the user's machine.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"A firewall allows e-mail traffic because it is legitimate; the malicious code runs only when the user opens it. That is exactly why A holds, so R explains A. Antivirus and user awareness are needed in addition.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL"}
];

export default questions;
